(function(){'use strict';
const M=OpsModel,U=OpsUI,S=OpsStorage,C=window.CURRICULUM;
let loaded=S.load(C),state=loaded.state,planMode='week',planDate=M.today(state),topicSearch='',sourceFilter='Все',debtRecommended=false;
const nav=[['home','Главная'],['topics','Темы'],['plan','План'],['debts','Долги'],['progress','Прогресс'],['settings','Настройки']];
const sources=['Все','Мой план','Яндекс Практикум','Просто DevOps','LinkMeUp','Custom'];
const typeOrder=Object.keys(M.TYPES),typeIcon=U.icon;
function id(prefix){return `${prefix}-${Date.now().toString(36)}-${Math.random().toString(36).slice(2,7)}`}
function save(msg='Сохранено'){if(!loaded.recovery){S.save(state);document.getElementById('save-status').textContent='Сохранено '+new Date().toLocaleTimeString('ru-RU',{hour:'2-digit',minute:'2-digit'});}if(msg)U.toast(msg)}
function routeParts(){return (location.hash.slice(1)||'home').split('/').map(decodeURIComponent)}
function currentRoute(){return routeParts()[0]}
function taskTopic(t){return state.topics.find(x=>x.id===t.topicId)}
function statusClass(s){return s==='По графику'||s==='Опережаю план'?'good':s.includes('Серьёзное')?'bad':'warn'}
function renderNav(){document.getElementById('nav').innerHTML=nav.map(([rid,label])=>`<a class="nav-link ${currentRoute()===rid?'active':''}" href="#${rid}">${label}${rid==='debts'?'<span class="nav-debt"></span>':''}</a>`).join('')}
function typeGroups(tasks){return typeOrder.map(type=>[type,tasks.filter(t=>t.type===type)]).filter(x=>x[1].length).map(([type,list])=>`<section class="task-group"><div class="task-group-label">${typeIcon[type]} ${U.e(M.TYPES[type])}<span>· ${list.length}</span></div><div class="task-list">${list.map(U.taskRow).join('')}</div></section>`).join('')}
function pageHead(label,title,description,actions=''){return `<div class="page-head"><div><div class="eyebrow">${U.e(label)}</div><h1>${U.e(title)}</h1><p>${U.e(description)}</p></div>${actions?`<div class="page-actions">${actions}</div>`:''}</div>`}
function empty(text){return `<div class="empty">${U.e(text)}</div>`}
function home(){const day=M.today(state),s=M.stats(state,day),today=state.tasks.filter(t=>t.scheduledDate===day),next=M.recommend(state).slice(0,3),key=state.topics.map(t=>({t,p:M.progress(state.tasks.filter(x=>x.topicId===t.id))})).filter(x=>x.p.total).slice(0,5);return `${pageHead('Командный центр','Сегодняшний маршрут','Конкретные задачи, состояние графика и следующий разумный шаг.','<button class="ghost-button" data-action="add-task">+ Своя задача</button><button class="button" data-action="finish-day">Завершить день</button>')}${loaded.error?`<div class="notice error">${U.e(loaded.error)}</div>`:''}<section class="dashboard-grid"><article class="panel mission-card"><div class="mission-top"><div><div class="mono-label">Сегодня · ${U.date(day)}</div><div class="date-big">Неделя ${s.studyWeek} <span>/ учебный день ${s.studyDay}</span></div></div><span class="signal ${statusClass(s.status)}">${s.status}</span></div><div class="metric-strip"><div class="metric"><strong>${today.length}</strong><span>задач сегодня</span></div><div class="metric"><strong>${today.filter(t=>t.completed).length}</strong><span>выполнено</span></div><div class="metric"><strong>${today.filter(t=>!t.completed).length}</strong><span>осталось</span></div><div class="metric"><strong>${s.debts.length}</strong><span>просрочено</span></div></div></article><article class="panel score-card"><div class="ring" style="--p:${s.total.percent}"><div class="ring-value">${s.total.percent}%<span>весь план</span></div></div><div class="score-lines"><div class="score-line"><span>По плану</span><b>${s.expected}%</b></div><div class="score-line"><span>Фактически</span><b>${s.total.percent}%</b></div><div class="delta ${s.delta<0?'negative':'positive'}">${s.delta>0?'+':''}${s.delta}%</div><span class="mono-label">${s.delta<0?'от графика':'к плану'}</span></div></article></section><section class="content-grid"><article class="panel section-card"><div class="section-title"><div><div class="eyebrow">Фокус дня</div><h2>План на сегодня</h2></div><span class="status-pill">${s.today.done} / ${s.today.total}</span></div>${today.length?`<div class="task-groups">${typeGroups(today)}</div>`:empty('На эту дату задач нет. Можно взять следующий пункт из очереди.')}</article><aside class="side-stack"><article class="panel section-card"><div class="section-title"><h2>Next up</h2><span class="mono-label">по зависимостям</span></div><ol class="next-list">${next.map(t=>`<li><button class="task-title-button" data-task="${U.e(t.id)}" data-action="open-task"><strong>${U.e(t.title)}</strong><small>${U.e(taskTopic(t)?.title)} · ${t.scheduledDate?U.shortDate(t.scheduledDate):'без даты'}</small></button></li>`).join('')}</ol></article><article class="panel section-card"><div class="section-title"><h2>Темп</h2><span class="mono-label">4 горизонта</span></div><div class="mini-bars">${[['Сегодня',s.today.percent],['Неделя',s.week.percent],['Месяц',s.month.percent],['Весь план',s.total.percent]].map(([x,p])=>`<div class="bar-row"><span>${x}</span>${U.progressBar(p)}<b>${p}%</b></div>`).join('')}</div></article><article class="panel section-card"><div class="section-title"><h2>Серия</h2><span class="mono-label">${s.streak.studiedToday?'сегодня учился':'ждёт старта'}</span></div><div class="streak-grid"><div class="streak-item"><strong>${s.streak.current}</strong><span>текущая</span></div><div class="streak-item"><strong>${s.streak.longest}</strong><span>лучшая</span></div></div></article><article class="panel section-card"><div class="section-title"><h2>Направления</h2><a href="#topics" class="mono-label">все темы →</a></div><div class="mini-bars">${key.map(x=>`<div class="bar-row"><span>${U.e(x.t.title)}</span>${U.progressBar(x.p.percent)}<b>${x.p.percent}%</b></div>`).join('')}</div></article></aside></section>`}
function sourceChips(){return `<div class="chips" aria-label="Фильтр по источнику">${sources.map(s=>`<button class="chip ${sourceFilter===s?'active':''}" data-action="source-filter" data-source="${U.e(s)}">${U.e(s)}</button>`).join('')}</div>`}
function taskVisible(t){const q=topicSearch.trim().toLowerCase();const source=sourceFilter==='Все'||t.source===sourceFilter||(t.sources||[]).includes(sourceFilter)||(sourceFilter==='Custom'&&t.custom);return source&&(!q||[t.title,t.description,t.source,(t.sources||[]).join(' ')].join(' ').toLowerCase().includes(q))}
function topicCard(topic){const all=state.tasks.filter(t=>t.topicId===topic.id),visible=all.filter(taskVisible),p=M.progress(all),found=topicSearch||sourceFilter!=='Все'?visible.length:null;return `<a class="topic-card panel" href="#topics/${topic.id}"><div class="topic-index">${String(topic.order+1).padStart(2,'0')}</div><div class="topic-card-main"><div class="section-title"><h2>${U.e(topic.title)}</h2><span class="signal ${p.percent===100?'good':p.percent?'warn':''}">${p.percent===100?'Готово':p.percent?'В процессе':'Не начато'}</span></div><p>${U.e(topic.description)}</p>${U.progressBar(p.percent)}<div class="topic-foot"><span>${p.done} / ${p.total} обязательных</span><b>${p.percent}%</b>${found!==null?`<span>${found} совпадений</span>`:''}</div></div></a>`}
function topicsList(){const q=topicSearch.toLowerCase().trim();const list=state.topics.filter(topic=>{const related=state.tasks.filter(t=>t.topicId===topic.id);return (!q||topic.title.toLowerCase().includes(q)||topic.description.toLowerCase().includes(q)||related.some(taskVisible))&&(sourceFilter==='Все'||related.some(taskVisible))});return `${pageHead('Карта компетенций','Темы','Единая иерархия: одинаковые темы из трёх источников собраны вместе.','<button class="ghost-button" data-action="add-topic">+ Своя тема</button>')}<section class="panel search-panel"><label class="search-box"><span>⌕</span><input id="topic-search" type="search" placeholder="Найти BGP, задание или источник" value="${U.e(topicSearch)}" autocomplete="off"></label>${sourceChips()}<div class="search-count">${list.length} тем · ${state.subtopics.length} подтем · ${state.tasks.length} учебных элементов</div></section><section class="topic-grid">${list.map(topicCard).join('')||empty('По этому запросу ничего не найдено.')}</section>`}
function topicDetail(topicId){const topic=state.topics.find(x=>x.id===topicId);if(!topic)return topicsList();const subs=state.subtopics.filter(x=>x.topicId===topic.id).sort((a,b)=>a.order-b.order),p=M.progress(state.tasks.filter(t=>t.topicId===topic.id));return `${pageHead(`Темы / ${topic.title}`,topic.title,topic.description,`<button class="ghost-button" data-action="add-subtopic" data-topic="${topic.id}">+ Подтема</button>${topic.custom?'<button class="mini-button danger" data-action="delete-topic" data-topic="'+topic.id+'">Удалить</button>':''}`)}<div class="breadcrumb"><a href="#topics">Темы</a><span>›</span><strong>${U.e(topic.title)}</strong></div><section class="panel topic-summary"><div class="ring compact" style="--p:${p.percent}"><div class="ring-value">${p.percent}%<span>core</span></div></div><div><div class="summary-numbers"><strong>${p.done}</strong><span>из ${p.total} обязательных</span><strong>${p.bonusDone}</strong><span>из ${p.bonusTotal} бонусных</span></div>${U.progressBar(p.percent)}</div></section><section class="subtopic-list">${subs.map(sub=>{const tasks=state.tasks.filter(t=>t.subtopicId===sub.id),sp=M.progress(tasks),theory=M.progress(tasks.filter(t=>['Theory','Reading','Video','Quiz'].includes(t.type))),practice=M.progress(tasks.filter(t=>['Practice','Lab','Project'].includes(t.type)));return `<a class="subtopic-row panel" href="#topics/${topic.id}/${sub.id}"><div><span class="mono-label">${String(sub.order+1).padStart(2,'0')}</span><h2>${U.e(sub.title)}</h2><div class="sub-meta"><span>Теория ${theory.percent}%</span><span>Практика ${practice.percent}%</span><span>${new Set(tasks.flatMap(t=>t.sources||[t.source])).size} источника</span></div></div><div class="sub-progress">${U.progressBar(sp.percent)}<b>${sp.percent}%</b><span>${sp.done} / ${sp.total}</span></div><span class="chevron">›</span></a>`}).join('')}</section>`}
function prereqLabel(sub){return (sub.prerequisites||[]).map(pid=>state.subtopics.find(x=>x.id===pid)?.title).filter(Boolean)}
function subtopicDetail(topicId,subId){const topic=state.topics.find(x=>x.id===topicId),sub=state.subtopics.find(x=>x.id===subId);if(!topic||!sub)return topicDetail(topicId);const tasks=state.tasks.filter(t=>t.subtopicId===sub.id&&taskVisible(t)),all=state.tasks.filter(t=>t.subtopicId===sub.id),p=M.progress(all),theory=M.progress(all.filter(t=>['Theory','Reading','Video','Quiz'].includes(t.type))),practice=M.progress(all.filter(t=>['Practice','Lab','Project'].includes(t.type))),mins=all.reduce((a,t)=>a+t.estimatedMinutes,0),src=[...new Set(all.flatMap(t=>t.sources||[t.source]))],pre=prereqLabel(sub);return `${pageHead(`${topic.title} / Подтема`,sub.title,'Все материалы источников в одной карточке.',`<button class="ghost-button ${state.reviewQueue.includes(sub.id)?'active':''}" data-action="toggle-review" data-subtopic="${sub.id}">↻ ${state.reviewQueue.includes(sub.id)?'В очереди повторения':'Нужно повторить'}</button><button class="ghost-button" data-action="add-task" data-topic="${topic.id}" data-subtopic="${sub.id}">+ Задача</button>${sub.custom?'<button class="mini-button danger" data-action="delete-subtopic" data-subtopic="'+sub.id+'">Удалить</button>':''}`)}<div class="breadcrumb"><a href="#topics">Темы</a><span>›</span><a href="#topics/${topic.id}">${U.e(topic.title)}</a><span>›</span><strong>${U.e(sub.title)}</strong></div><section class="panel detail-metrics"><div><span>Progress</span><strong>${p.percent}%</strong></div><div><span>Theory</span><strong>${theory.percent}%</strong></div><div><span>Practice</span><strong>${practice.percent}%</strong></div><div><span>Время</span><strong>${Math.floor(mins/60)}ч ${mins%60}м</strong></div><div><span>Выполнено</span><strong>${p.done} / ${p.total}</strong></div></section>${pre.length?`<div class="notice">Сначала рекомендуется: ${pre.map(U.e).join(', ')}. Это подсказка, задания остаются доступными.</div>`:''}<section class="panel source-panel"><div><span class="mono-label">Источники</span><div class="source-list">${src.map(s=>`<span class="source-pill">${U.e(s)}</span>`).join('')}</div></div>${sourceChips()}</section><section class="panel section-card">${tasks.length?`<div class="task-groups">${typeGroups(tasks)}</div>`:empty('В выбранном источнике подходящих заданий нет.')}</section>`}
function topics(){const [,topicId,subId]=routeParts();return subId?subtopicDetail(topicId,subId):topicId?topicDetail(topicId):topicsList()}
function changePeriod(n){if(planMode==='day')planDate=M.addDays(planDate,n);else if(planMode==='week')planDate=M.addDays(planDate,n*7);else{const d=M.parse(planDate);d.setMonth(d.getMonth()+n);planDate=M.iso(d)}}
function planToolbar(){return `<div class="plan-toolbar panel"><div class="segmented">${['day','week','month'].map(x=>`<button class="${planMode===x?'active':''}" data-action="plan-mode" data-mode="${x}">${{day:'День',week:'Неделя',month:'Месяц'}[x]}</button>`).join('')}</div><div class="period-nav"><button class="icon-button" data-action="plan-prev" aria-label="Предыдущий период">‹</button><button class="ghost-button" data-action="plan-today">Текущий период</button><button class="icon-button" data-action="plan-next" aria-label="Следующий период">›</button></div></div>`}
function dayCard(day,full=true){const tasks=state.tasks.filter(t=>t.scheduledDate===day),p=M.progress(tasks),past=day<M.today(state)&&p.done<p.total;return `<article class="day-card panel ${day===M.today(state)?'today':''} ${past?'overdue-day':''}"><button class="day-head" data-action="plan-date" data-date="${day}"><span>${U.shortDate(day)}</span><b>${p.percent}%</b></button><div class="day-status">${past?'Просрочено':p.percent===100&&p.total?'Выполнено':p.done?'Частично':p.total?'Не начато':'Выходной'}</div>${full?`<div class="task-list compact-list">${tasks.map(U.taskRow).join('')||'<span class="rest-day">Нет задач</span>'}</div>`:`<div class="day-dots">${tasks.slice(0,8).map(t=>`<i class="${t.completed?'done':''}"></i>`).join('')}</div><small>${tasks.length} задач</small>`}</article>`}
function plan(){let body,title;if(planMode==='day'){title=U.date(planDate);body=dayCard(planDate,true)}else if(planMode==='week'){const start=M.weekStart(planDate);title=`${U.shortDate(start)} — ${U.date(M.addDays(start,6))}`;body=`<div class="week-grid">${Array.from({length:7},(_,i)=>dayCard(M.addDays(start,i),true)).join('')}</div>`}else{const d=M.parse(planDate),first=M.iso(new Date(d.getFullYear(),d.getMonth(),1,12)),last=M.iso(new Date(d.getFullYear(),d.getMonth()+1,0,12)),offset=(M.parse(first).getDay()+6)%7,cells=Array.from({length:offset},()=>'<div></div>');for(let x=first;x<=last;x=M.addDays(x,1))cells.push(dayCard(x,false));title=new Intl.DateTimeFormat('ru-RU',{month:'long',year:'numeric'}).format(d);body=`<div class="month-weekdays">${['Пн','Вт','Ср','Чт','Пт','Сб','Вс'].map(x=>`<span>${x}</span>`).join('')}</div><div class="month-grid">${cells.join('')}</div>`}return `${pageHead('Календарь','Учебный план','Word-план задаёт недели; задачи внутри недели распределены по доступной нагрузке.','<button class="ghost-button" data-action="add-task">+ Задача</button>')}${planToolbar()}<div class="period-title"><h2>${U.e(title)}</h2><span class="mono-label">Нажмите задачу, чтобы изменить дату</span></div>${body}`}
function debts(){const day=M.today(state),debts=M.overdue(state.tasks,day),s=M.stats(state,day),ordered=debtRecommended?M.recommend(state,debts,day):[...debts].sort((a,b)=>a.scheduledDate.localeCompare(b.scheduledDate)),groups=debtRecommended?[['Рекомендуемый порядок',ordered]]:[...new Set(ordered.map(t=>t.scheduledDate))].map(d=>[d,ordered.filter(t=>t.scheduledDate===d)]);return `${pageHead('Контроль отставания','Учебный долг','Просроченные обязательные задания исчезают отсюда сразу после выполнения.',`<button class="${debtRecommended?'button':'ghost-button'}" data-action="debt-order">${debtRecommended?'Показан рекомендуемый порядок':'Показать рекомендуемый порядок'}</button>`)}<section class="debt-summary panel"><div><span>Общий долг</span><strong>${debts.length}</strong><small>заданий</small></div><div><span>Отставание</span><strong>${s.debtDays}</strong><small>учебных дней</small></div><div><span>Факт / план</span><strong>${s.delta>0?'+':''}${s.delta}%</strong><small>${s.status}</small></div></section>${groups.length?`<section class="debt-groups">${groups.map(([date,tasks])=>`<article class="panel debt-day"><div class="debt-date"><div><span class="mono-label">${debtRecommended?'Алгоритм: дата → зависимости → приоритет':'Дата долга'}</span><h2>${debtRecommended?'Следующие задачи':U.date(date)}</h2></div><span>${tasks.length} шт.</span></div><div class="task-list">${tasks.map(t=>{const p=M.debtPriority(state,t,day),blocks=M.unresolved(state,t);return `<div class="debt-task ${p.label.toLowerCase()}">${U.taskRow(t)}<div class="debt-reason"><span class="priority-dot"></span>${p.label} · ${p.age} дн.${p.blocking?' · блокирует следующие темы':''}${blocks.length?' · есть незакрытые prerequisites':''}</div></div>`}).join('')}</div></article>`).join('')}</section>`:empty('Долгов нет. План на сегодня остаётся на главной.')}`}
function linePath(points,key,w=800,h=260){return points.map((p,i)=>[p,i]).filter(([p])=>p[key]!==null).map(([p,i],n)=>`${n?'L':'M'} ${Math.round(i/Math.max(1,points.length-1)*w)} ${Math.round(h-p[key]/100*h)}`).join(' ')}
function progressPage(){const day=M.today(state),s=M.stats(state,day),points=M.history(state,state.settings.startDate,C.endDate,7),byTopic=state.topics.map(t=>({t,p:M.progress(state.tasks.filter(x=>x.topicId===t.id))})),byType=typeOrder.map(type=>{const items=state.tasks.filter(t=>t.type===type);return{type,done:items.filter(t=>t.completed).length,total:items.length}}).filter(x=>x.total),net=byTopic.find(x=>x.t.id==='network')?.p.percent||0,docker=byTopic.find(x=>x.t.id==='docker')?.p.percent||0,ach=[['Первая лаборатория',state.tasks.some(t=>t.type==='Lab'&&t.completed)],['Серия 7 дней',s.streak.longest>=7],['Networking 25%',net>=25],['Networking 50%',net>=50],['Первый проект',state.tasks.some(t=>t.type==='Project'&&t.completed)],['Docker завершён',docker===100]],heat=Array.from({length:140},(_,i)=>{const d=M.addDays(day,i-139),n=state.tasks.filter(t=>t.completedAt?.slice(0,10)===d&&t.completed).length;return `<i title="${d}: ${n} заданий" class="heat h${Math.min(4,n)}"></i>`}).join('');return `${pageHead('Аналитика','Прогресс','Фактическая траектория строится только по вашим отметкам выполнения.')}<section class="progress-hero"><article class="panel score-card progress-score"><div class="ring" style="--p:${s.total.percent}"><div class="ring-value">${s.total.percent}%<span>core</span></div></div><div><div class="delta ${s.delta<0?'negative':'positive'}">${s.delta>0?'+':''}${s.delta}%</div><p>${U.e(s.status)} · план ${s.expected}%</p><div class="streak-grid"><div class="streak-item"><strong>${s.doneWeek}</strong><span>за неделю</span></div><div class="streak-item"><strong>${s.doneMonth}</strong><span>за месяц</span></div><div class="streak-item"><strong>${s.average}%</strong><span>среднее за день</span></div><div class="streak-item"><strong>${s.streak.current}</strong><span>текущая серия</span></div></div></div></article><article class="panel section-card"><div class="section-title"><h2>По типам</h2><span class="mono-label">выполнено / всего</span></div><div class="type-stats">${byType.map(x=>`<div><span>${typeIcon[x.type]} ${U.e(M.TYPES[x.type])}</span><b>${x.done} / ${x.total}</b></div>`).join('')}</div></article></section><section class="panel chart-card"><div class="section-title"><div><h2>Progress over time</h2><p>Плановая и фактическая доля обязательных элементов</p></div><div class="chart-legend"><span><i class="planned"></i>Planned</span><span><i class="actual"></i>Actual</span></div></div><svg viewBox="0 0 800 280" role="img" aria-label="График планового и фактического прогресса"><g class="grid-lines">${[0,25,50,75,100].map(v=>`<path d="M0 ${260-v*2.6} H800"></path><text x="4" y="${254-v*2.6}">${v}%</text>`).join('')}</g><path class="chart-line planned" d="${linePath(points,'planned',800,260)}"></path><path class="chart-line actual" d="${linePath(points,'actual',800,260)}"></path></svg></section><section class="analytics-grid"><article class="panel section-card"><div class="section-title"><h2>Направления</h2><span class="mono-label">взвешено по заданиям</span></div><div class="topic-progress-list">${byTopic.map(x=>`<a href="#topics/${x.t.id}"><span>${U.e(x.t.title)}</span>${U.progressBar(x.p.percent)}<b>${x.p.percent}%</b></a>`).join('')}</div></article><aside class="side-stack"><article class="panel section-card"><div class="section-title"><h2>Активность</h2><span class="mono-label">20 недель</span></div><div class="heatmap">${heat}</div><div class="heat-legend">меньше <i class="heat h1"></i><i class="heat h2"></i><i class="heat h3"></i><i class="heat h4"></i> больше</div></article><article class="panel section-card"><div class="section-title"><h2>Повторить</h2><span class="mono-label">${state.reviewQueue.length} тем</span></div>${state.reviewQueue.length?`<div class="review-list">${state.reviewQueue.map(qid=>{const sub=state.subtopics.find(x=>x.id===qid),topic=state.topics.find(x=>x.id===sub?.topicId);return sub?`<a href="#topics/${topic.id}/${sub.id}">↻ ${U.e(sub.title)}</a>`:''}).join('')}</div>`:empty('Очередь повторения пуста.')}</article><article class="panel section-card"><div class="section-title"><h2>Достижения</h2><span class="mono-label">вторично</span></div><div class="achievement-grid">${ach.map(([x,on])=>`<span class="${on?'unlocked':''}">◇ ${U.e(x)}</span>`).join('')}</div></article></aside></section><section class="panel section-card notes-card"><div class="section-title"><h2>Quick notes</h2><span class="mono-label">сохраняются автоматически</span></div><textarea id="quick-notes" placeholder="Например: повторить route preference…">${U.e(state.quickNotes)}</textarea></section>`}
function settings(){const ds=['Вс','Пн','Вт','Ср','Чт','Пт','Сб'];return `${pageHead('Управление','Настройки','Календарь, рабочая нагрузка, тема и резервная копия.')}<form id="settings-form" class="settings-grid"><section class="panel section-card"><div class="section-title"><h2>Календарь</h2><span class="mono-label">часовой пояс браузера</span></div><div class="form-grid"><div class="field"><label for="start-date">Дата начала</label><input id="start-date" name="startDate" type="date" value="${state.settings.startDate}" required></div><div class="field"><label for="reference-date">Дата для просмотра</label><input id="reference-date" name="referenceDate" type="date" value="${state.settings.referenceDate||''}"><small>Пусто — использовать текущую дату.</small></div><div class="field wide"><label>Учебные дни</label><div class="weekday-picker">${[1,2,3,4,5,6,0].map(d=>`<label><input type="checkbox" name="studyDay" value="${d}" ${state.settings.studyDays.includes(d)?'checked':''}><span>${ds[d]}</span></label>`).join('')}</div></div><div class="field"><label for="weekday-hours">Будний день, часов</label><input id="weekday-hours" name="weekdayHours" type="number" min="0.25" max="24" step="0.25" value="${state.settings.weekdayHours}" required></div><div class="field"><label for="weekend-hours">Выходной, часов</label><input id="weekend-hours" name="weekendHours" type="number" min="0.25" max="24" step="0.25" value="${state.settings.weekendHours}" required></div><div class="field"><label for="theme">Тема</label><select id="theme" name="theme"><option value="dark" ${state.settings.theme==='dark'?'selected':''}>Тёмная</option><option value="light" ${state.settings.theme==='light'?'selected':''}>Светлая</option></select></div></div><div class="modal-actions"><button class="button" type="submit">Сохранить настройки</button></div></section><aside class="side-stack"><section class="panel section-card"><div class="section-title"><h2>Backup</h2><span class="mono-label">JSON</span></div><p>Экспорт содержит прогресс, даты, заметки и пользовательские элементы. Импорт сначала проходит проверку структуры.</p><div class="stack-actions"><button class="button" type="button" data-action="export">Экспортировать</button><label class="ghost-button file-button">Импортировать<input id="import-file" type="file" accept="application/json,.json"></label><button class="mini-button danger" type="button" data-action="reset">Сбросить прогресс</button></div></section><section class="panel section-card"><div class="section-title"><h2>Состояние</h2><span class="mono-label">localStorage</span></div><div class="source-facts"><span>Схема <b>v${state.schemaVersion}</b></span><span>Каталог <b>v${state.catalogVersion}</b></span><span>Задач <b>${state.tasks.length}</b></span><span>Последнее сохранение <b>${state.savedAt?new Date(state.savedAt).toLocaleString('ru-RU'):'ещё нет'}</b></span></div></section></aside></form><section class="sources-section"><div class="section-title"><div><h2>Что извлечено из материалов</h2><p>Приложение хранит ссылки на происхождение каждого элемента.</p></div></div><div class="source-cards">${C.sourceSummary.map(x=>`<article class="panel source-card"><div class="mono-label">${U.e(x.id)}</div><h2>${U.e(x.title)}</h2><p>${U.e(x.note)}</p><div class="source-facts">${Object.entries(x).filter(([k])=>!['id','title','file','note'].includes(k)).map(([k,v])=>`<span>${U.e(k)} <b>${U.e(v)}</b></span>`).join('')}</div></article>`).join('')}</div></section>`}
function render(){renderNav();document.documentElement.dataset.theme=state.settings.theme;const pages={home,topics,plan,debts,progress:progressPage,settings};document.getElementById('main').innerHTML=(pages[currentRoute()]||home)();document.querySelectorAll('.nav-debt').forEach(el=>{const n=M.overdue(state.tasks,M.today(state)).length;el.textContent=n?String(n):''});document.title=`${nav.find(x=>x[0]===currentRoute())?.[1]||'OpsTrack'} · OpsTrack`}
function toggleTask(taskId){const t=state.tasks.find(x=>x.id===taskId);if(!t)return;t.completed=!t.completed;t.completedAt=t.completed?M.today(state)+'T12:00:00.000Z':null;state.activity.push({taskId,date:M.today(state),completed:t.completed});save(t.completed?'Задание выполнено':'Отметка снята');render()}
function taskSources(t){const refs=t.sourceRefs||[];return `<section class="modal-sources"><span class="mono-label">Источники</span><div class="source-list">${(t.sources||[t.source]).map(s=>`<span class="source-pill">${U.e(s)}</span>`).join('')}</div>${refs.map(r=>r.url?`<a href="${U.e(r.url)}" target="_blank" rel="noopener noreferrer">${U.e(r.label)} ↗</a>`:`<span>${U.e(r.label)}</span>`).join('')}${t.sourceAccess?`<div class="notice">${U.e(t.sourceAccess)}</div>`:''}</section>`}
function taskForm(task,defaults={}){const editing=Boolean(task),t=task||{title:'',description:'',topicId:defaults.topic||state.topics[0].id,subtopicId:defaults.subtopic||'',source:'Custom',type:'Practice',scheduledDate:M.today(state),estimatedMinutes:30,completed:false,optional:false,priority:'medium',notes:'',custom:true},subs=state.subtopics.filter(x=>x.topicId===t.topicId);if(!t.subtopicId)t.subtopicId=subs[0]?.id||'';U.modal(`<form id="task-form" data-task="${editing?U.e(t.id):''}" class="modal-body"><div class="modal-head"><div><div class="eyebrow">${editing?'Редактирование':'Новая задача'}</div><h2 id="modal-title">${editing?U.e(t.title):'Добавить задачу'}</h2></div><button type="button" class="icon-button" data-action="close-modal" aria-label="Закрыть">×</button></div><div class="form-grid"><div class="field wide"><label>Название</label><input name="title" required maxlength="500" value="${U.e(t.title)}"></div><div class="field"><label>Тема</label><select name="topicId" data-action="task-topic">${state.topics.map(x=>`<option value="${x.id}" ${x.id===t.topicId?'selected':''}>${U.e(x.title)}</option>`).join('')}</select></div><div class="field"><label>Подтема</label><select name="subtopicId">${subs.map(x=>`<option value="${x.id}" ${x.id===t.subtopicId?'selected':''}>${U.e(x.title)}</option>`).join('')}</select></div><div class="field"><label>Тип</label><select name="type">${typeOrder.map(x=>`<option value="${x}" ${x===t.type?'selected':''}>${U.e(M.TYPES[x])}</option>`).join('')}</select></div><div class="field"><label>Приоритет</label><select name="priority">${['critical','high','medium','low'].map(x=>`<option value="${x}" ${x===t.priority?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label>Дата</label><input name="scheduledDate" type="date" value="${t.scheduledDate||''}"></div><div class="field"><label>Оценка, минут</label><input name="estimatedMinutes" type="number" min="0" max="10000" value="${t.estimatedMinutes}"></div><div class="field wide"><label>Описание</label><textarea name="description">${U.e(t.description)}</textarea></div><div class="field wide"><label>Заметки</label><textarea name="notes">${U.e(t.notes)}</textarea></div><label class="check-field"><input name="optional" type="checkbox" ${t.optional?'checked':''}> Необязательное задание</label></div>${editing?taskSources(t):''}<div class="modal-actions">${editing&&t.custom?'<button type="button" class="mini-button danger" data-action="delete-task">Удалить</button>':''}<button type="button" class="ghost-button" data-action="close-modal">Отмена</button><button class="button" type="submit">${editing?'Сохранить':'Добавить'}</button></div></form>`)}
function finishDay(){const day=M.today(state),tasks=state.tasks.filter(t=>t.scheduledDate===day&&!t.completed);U.modal(`<form id="finish-form" class="modal-body"><div class="modal-head"><div><div class="eyebrow">Итоги дня</div><h2 id="modal-title">Завершить ${U.shortDate(day)}</h2></div><button type="button" class="icon-button" data-action="close-modal">×</button></div><p>Выполнено ${state.tasks.filter(t=>t.scheduledDate===day&&t.completed).length} / ${state.tasks.filter(t=>t.scheduledDate===day).length}. Осталось ${tasks.length}.</p>${tasks.length?`<div class="choice-list"><label><input type="radio" name="finishChoice" value="tomorrow" checked><span><b>Перенести на завтра</b><small>${U.date(M.addDays(day,1))}</small></span></label><label><input type="radio" name="finishChoice" value="debt"><span><b>Оставить задолженностью</b><small>Даты не изменятся</small></span></label><label><input type="radio" name="finishChoice" value="custom"><span><b>Выбрать дату</b><input type="date" name="customDate" value="${M.addDays(day,1)}"></span></label></div>`:'<div class="notice">Все задачи на сегодня выполнены.</div>'}<div class="modal-actions"><button type="button" class="ghost-button" data-action="close-modal">Отмена</button><button class="button" type="submit">Завершить день</button></div></form>`)}
function simpleEntityForm(kind,topicId){const isTopic=kind==='topic';U.modal(`<form id="entity-form" data-kind="${kind}" data-topic="${topicId||''}" class="modal-body"><div class="modal-head"><div><div class="eyebrow">Свой материал</div><h2 id="modal-title">Добавить ${isTopic?'тему':'подтему'}</h2></div><button type="button" class="icon-button" data-action="close-modal">×</button></div><div class="field"><label>Название</label><input name="title" required maxlength="200"></div>${isTopic?'<div class="field"><label>Краткое описание</label><textarea name="description"></textarea></div>':''}<div class="modal-actions"><button type="button" class="ghost-button" data-action="close-modal">Отмена</button><button class="button">Добавить</button></div></form>`)}
function exportBackup(){const blob=new Blob([S.backup(state)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`devops-tracker-backup-${M.today(state)}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);U.toast('Backup экспортирован')}
function resetState(){if(!confirm('Сбросить все отметки, переносы и пользовательские данные? Сначала сделайте экспорт, если они нужны.'))return;state=S.initial(C);loaded={state,error:null};save('Прогресс сброшен');planDate=M.today(state);render()}
function registerWebMCP(){const ctx=document.modelContext;if(!ctx?.registerTool)return;const tools=[{name:'read_today_plan',title:'Прочитать план на сегодня',description:'Возвращает сегодняшние задачи и вычисленную задолженность без изменения данных.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:false},execute:()=>{const d=M.today(state);return{date:d,tasks:state.tasks.filter(t=>t.scheduledDate===d).map(t=>({id:t.id,title:t.title,completed:t.completed})),overdue:M.overdue(state.tasks,d).length}}},{name:'complete_study_tasks',title:'Выполнить учебные задачи',description:'Отмечает один или несколько существующих учебных элементов выполненными и обновляет видимый прогресс.',inputSchema:{type:'object',properties:{taskIds:{type:'array',items:{type:'string'},minItems:1,uniqueItems:true}},required:['taskIds'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute:({taskIds})=>{if(!Array.isArray(taskIds)||taskIds.some(x=>!state.tasks.some(t=>t.id===x)))throw Error('Неизвестный taskId');taskIds.forEach(x=>{const t=state.tasks.find(y=>y.id===x);t.completed=true;t.completedAt=M.today(state)+'T12:00:00.000Z'});save(null);render();return{completed:taskIds.length,totalProgress:M.progress(state.tasks).percent}}}];tools.forEach(t=>Promise.resolve(ctx.registerTool(t)).catch(()=>{}))}
document.addEventListener('change',e=>{if(e.target.dataset.action==='toggle')toggleTask(e.target.closest('[data-task]').dataset.task);if(e.target.dataset.action==='task-topic'){const select=e.target.form.elements.subtopicId;select.innerHTML=state.subtopics.filter(x=>x.topicId===e.target.value).map(x=>`<option value="${x.id}">${U.e(x.title)}</option>`).join('')}if(e.target.id==='import-file'&&e.target.files[0]){const reader=new FileReader();reader.onload=()=>{try{const imported=JSON.parse(reader.result);delete imported.app;delete imported.exportedAt;state=S.validate(imported);loaded={state,error:null};S.save(state);planDate=M.today(state);U.toast('Backup импортирован');render()}catch(err){U.toast(err.message)}};reader.readAsText(e.target.files[0])}});
document.addEventListener('input',e=>{if(e.target.id==='topic-search'){topicSearch=e.target.value;render();const q=document.getElementById('topic-search');q?.focus();q?.setSelectionRange(q.value.length,q.value.length)}if(e.target.id==='quick-notes'){state.quickNotes=e.target.value;clearTimeout(window.noteTimer);window.noteTimer=setTimeout(()=>save(null),500)}});
document.addEventListener('submit',e=>{e.preventDefault();const f=e.target;if(f.id==='task-form'){const data=new FormData(f),existing=state.tasks.find(x=>x.id===f.dataset.task),values={title:String(data.get('title')).trim(),topicId:data.get('topicId'),subtopicId:data.get('subtopicId'),type:data.get('type'),priority:data.get('priority'),scheduledDate:data.get('scheduledDate')||null,estimatedMinutes:Number(data.get('estimatedMinutes')),description:String(data.get('description')),notes:String(data.get('notes')),optional:data.has('optional'),manuallyScheduled:true};if(existing)Object.assign(existing,values);else state.tasks.push({id:id('custom-task'),source:'Custom',sources:['Custom'],completed:false,completedAt:null,custom:true,sourceRefs:[],scheduleOrigin:'Добавлено вручную',...values});save(existing?'Задача обновлена':'Задача добавлена');U.closeModal();render()}if(f.id==='finish-form'){const choice=new FormData(f).get('finishChoice'),day=M.today(state),ids=state.tasks.filter(t=>t.scheduledDate===day&&!t.completed).map(t=>t.id);if(choice==='tomorrow')M.moveTasks(state,ids,M.addDays(day,1));if(choice==='custom')M.moveTasks(state,ids,f.elements.customDate.value);save(choice==='debt'?'День завершён, долг сохранён':'День завершён, задачи перенесены');U.closeModal();render()}if(f.id==='entity-form'){const data=new FormData(f),title=String(data.get('title')).trim();if(f.dataset.kind==='topic'){const tid=id('custom-topic');state.topics.push({id:tid,title,description:String(data.get('description')),category:'Custom',prerequisites:[],order:state.topics.length,custom:true});const sid=id('custom-subtopic');state.subtopics.push({id:sid,topicId:tid,title:'Основное',order:0,prerequisites:[],custom:true});save('Тема добавлена');U.closeModal();location.hash='topics/'+tid}else{const sid=id('custom-subtopic');state.subtopics.push({id:sid,topicId:f.dataset.topic,title,order:state.subtopics.filter(x=>x.topicId===f.dataset.topic).length,prerequisites:[],custom:true});save('Подтема добавлена');U.closeModal();location.hash=`topics/${f.dataset.topic}/${sid}`}}if(f.id==='settings-form'){const data=new FormData(f),days=data.getAll('studyDay').map(Number);if(!days.length){U.toast('Выберите хотя бы один учебный день');return}const newStart=data.get('startDate'),delta=M.diff(newStart,state.settings.startDate);if(delta)state.tasks.forEach(t=>{if(t.scheduledDate&&!t.manuallyScheduled)t.scheduledDate=M.addDays(t.scheduledDate,delta);if(t.originalDate&&!t.manuallyScheduled)t.originalDate=M.addDays(t.originalDate,delta)});state.settings={startDate:newStart,referenceDate:data.get('referenceDate'),studyDays:days,weekdayHours:Number(data.get('weekdayHours')),weekendHours:Number(data.get('weekendHours')),theme:data.get('theme')};planDate=M.today(state);save('Настройки сохранены');render()}});
document.addEventListener('click',e=>{const button=e.target.closest('[data-action]');if(!button)return;const row=button.closest('[data-task]'),action=button.dataset.action;if(action==='open-task'&&row)taskForm(state.tasks.find(x=>x.id===row.dataset.task));if(action==='add-task')taskForm(null,{topic:button.dataset.topic,subtopic:button.dataset.subtopic});if(action==='close-modal')U.closeModal();if(action==='finish-day')finishDay();if(action==='source-filter'){sourceFilter=button.dataset.source;render()}if(action==='plan-mode'){planMode=button.dataset.mode;render()}if(action==='plan-prev'){changePeriod(-1);render()}if(action==='plan-next'){changePeriod(1);render()}if(action==='plan-today'){planDate=M.today(state);render()}if(action==='plan-date'){planDate=button.dataset.date;planMode='day';render()}if(action==='debt-order'){debtRecommended=!debtRecommended;render()}if(action==='toggle-review'){const sid=button.dataset.subtopic,i=state.reviewQueue.indexOf(sid);i>=0?state.reviewQueue.splice(i,1):state.reviewQueue.push(sid);save(i>=0?'Убрано из повторения':'Добавлено в повторение');render()}if(action==='add-topic')simpleEntityForm('topic');if(action==='add-subtopic')simpleEntityForm('subtopic',button.dataset.topic);if(action==='delete-task'){const f=button.closest('form'),i=state.tasks.findIndex(x=>x.id===f.dataset.task);if(i>=0&&state.tasks[i].custom&&confirm('Удалить пользовательскую задачу?')){state.tasks.splice(i,1);save('Задача удалена');U.closeModal();render()}}if(action==='delete-subtopic'&&confirm('Удалить пользовательскую подтему и её задачи?')){const sid=button.dataset.subtopic;state.tasks=state.tasks.filter(x=>x.subtopicId!==sid);state.subtopics=state.subtopics.filter(x=>x.id!==sid);save('Подтема удалена');location.hash='topics'}if(action==='delete-topic'&&confirm('Удалить пользовательскую тему, её подтемы и задачи?')){const tid=button.dataset.topic;state.tasks=state.tasks.filter(x=>x.topicId!==tid);state.subtopics=state.subtopics.filter(x=>x.topicId!==tid);state.topics=state.topics.filter(x=>x.id!==tid);save('Тема удалена');location.hash='topics'}if(action==='export')exportBackup();if(action==='reset')resetState()});
document.getElementById('modal').addEventListener('click',e=>{if(e.target.id==='modal')U.closeModal()});
document.getElementById('theme-toggle').addEventListener('click',()=>{state.settings.theme=state.settings.theme==='dark'?'light':'dark';save('Тема изменена');render()});
window.addEventListener('hashchange',render);render();registerWebMCP();
})();
